def L(a,z):return '「'+''.join(T[a-1:z])+'」'
B=[
dict(a=1,z=5,star=2,lit=L(1,5),
key=[('圍困','H6696','tsarim','圍困'),('護衛兵','H4307','hamatarah','護衛處'),('囚','H3607','kaluy','關禁'),('西底家','H6667','tsidqiyahu','（人名）'),('迦勒底人','H3778','hakasdim','迦勒底人'),('口對口','H6310','piv','口'),('眷顧','H6485','piqdi','眷顧、察看')],
gram=['**{H4307}**（matarah，護衛處）：**耶利米被囚的地方，是「護衛兵的院」，在王宮之中。****這不是地牢，而是一個有人看守、可以見客的拘留處。**這就是為什麼**哈拿篾能夠進來**。','**{H6696}**（tsarim，圍困）：**這個字，描寫敵人的軍隊，把耶路撒冷圍得水洩不通。****耶利米寫下這一章的時候，城外是巴比倫的軍隊。**'],
exp=['三十二章的**時間，非常具體**：**西底家第十年，尼布甲尼撒十八年**，約是**主前587年**。**巴比倫的軍隊正圍困耶路撒冷，耶利米被關在王宮的護衛兵院內。****這是整卷書最黑暗的時刻之一。****就在這個時候，神的話臨到他。**','**他被囚的原因，是三節說的：他預言這城必被交在巴比倫王手中。****他說了真話，換來的是囚禁。****這一點，與三十章、三十一章的安慰之書形成強烈對比。****安慰的話，是在牢裡寫的。**','四、五節，神對西底家的宣告，**是很具體的**：**他不能逃脫，要被帶到巴比倫，「口對口彼此說話，眼對眼彼此相看」。****這是當面對質。****可是五節還有一個小小的字：「直到我眷顧他的時候」。****連這位最終被擄的王，神也沒有說完全沒有後事。**']),
dict(a=6,z=9,star=3,lit=L(6,9),
key=[('哈拿篾','H2601','khanamel','（人名）神施恩'),('叔叔','H1730','dod','叔叔、親屬'),('亞拿突','H6068','anatot','（地名）'),('買','H7069','qeneh','買、取得'),('承受','H3425','hayerushah','承受、得為業'),('舍客勒','H8255','shqalim','舍客勒（重量單位）'),('銀子','H3701','hakesef','銀子')],
gram=['**{H3425}**（yarash，承受）：「**合乎承受之理**」。**按照律法（利二十五25；民三十六章），一塊家族的田地，要留在家族裡。****哈拿篾來找耶利米，是照著這個規矩來的。**','**{H8255}**（shqalim，舍客勒）：「**十七舍客勒銀子**」。**這是一個很具體的數字，也是一個可以查證的交易。****耶利米把一個應許，放進了一張收據裡。**'],
exp=['**這一段，是整卷書最「生活」的一段。****神的話，先臨到耶利米：你的堂兄弟要來找你，叫你買他的地。****然後，哈拿篾果然來了，正好應驗神的話。****耶利米說：「就知道這是耶和華的話。」**（8節）','**請想一想這個場景：城被圍了，田地在敵人手中，隨時會被沒收。****這時候買地，在別人眼裡，是一個瘋狂的決定。****可是耶利米，照規矩，付了十七舍客勒銀子。****他的行動，把神的話，變成可以握在手中的東西。**','**這塊地，在亞拿突，是耶利米的老家，在便雅憫境內。****那是他被自己鄉里的人，想要殺害的地方**（十一21）。**神叫他，買下一塊這樣的地。****神的盼望，連他最痛的地方，也包括進去。**']),
dict(a=10,z=12,star=2,lit=L(10,12),
key=[('畫押','H3789','ektov','寫'),('封緘','H2856','ekhtom','蓋印'),('見證','H5749','veaed','作見證'),('天平','H3976','bamozanayim','天平'),('買契','H4736','hamiqneh','買契'),('巴錄','H1263','barukh','（人名）蒙福')],
gram=['**{H3976}**（mozen，天平）：「**用天平將銀子平給他**」。**古時候的銀子是秤重的。****每一個細節，都顯示這是一個完全合法、完全公開的交易。**','**{H1263}**（Barukh，巴錄）：**「蒙福」的意思。****這是巴錄第一次在耶利米書中，以名字出現。****他是耶利米的書記，後來在三十六章，他會成為更重要的角色。**'],
exp=['十到十二節，**所用的每一個動作，都是法律上的程序**：**畫押、封緘、請見證人、用天平平銀子，把買契交給巴錄。****兩份契：一份封緘（正本），一份敞著（副本，供人查閱）。****這是一個嚴謹的程序：正本存好，副本可以查。**','請留意：**這一切，是「**當著一切猶大人眼前**」進行的。****在一個被圍困的城裡，這個買地的事，被許多人看見。****耶利米不是在秘密中做的，而是公開地、讓人看見：我相信神的話。****信，有時是一種被人看見的行動。**','**巴錄**在這裡，是被交付買契的人。****神把一份關乎將來的文件，交給一位可靠的書記。****將來歸回的證據，就在他手中。']),
dict(a=13,z=15,star=3,lit=L(13,15),
key=[('瓦器','H2789','kheres','陶器'),('存留','H5975','yaamdu','站立、存留'),('多日','H3117','yamim rabim','許多日子'),('再買','H7069','yiqnu','買'),('房屋','H1004','batim','房屋'),('田地','H7704','vsadot','田地'),('葡萄園','H3754','vkramim','葡萄園')],
gram=['**{H2789}**（kheres，陶器）：「**放在瓦器裡**」。**古時候保存文件的方法，是把它們放在陶罐裡。****死海古卷，就是這樣保存下來的。****耶利米用當時最好的辦法，保存這份契約。**','**{H5975}**（amad，站立）：「**可以存留多日**」，直譯是「**使它們站立很多日**」。**神要這份契約，比這個圍困更長久。**'],
exp=['十四節，**神吩咐：把兩張契，放在瓦器裡，可以存留多日。****為什麼？因為將來，會有人再用到它們。****這份契約，是為一個目前看不見的未來準備的。**','十五節是**這一章的第一個盼望的宣告**：**「將來在這地必有人再買房屋、田地，和葡萄園。」****請留意三樣東西：房屋、田地、葡萄園，也就是居所、生計、與豐收。****這與二十九章5節的清單，呼應：蓋房屋、栽種田園、吃其中所產的。**','**這是一個很深的信心行動：在一個沒有未來的時候，為未來買了一塊地。****耶利米不是樂觀，他是相信神的話。****他知道城要被攻陷（三、四節），同時知道田地將被買賣（十五節）。****兩個信息，都是神說的，他兩個都相信。**']),
dict(a=16,z=19,star=3,lit=L(16,19),
key=[('禱告','H6419','vaetpallel','祈禱'),('大能','H3581','bekokhekha','能力'),('膀臂','H2220','uvizroakha','手臂'),('難成','H6381','yippale','奇妙、困難'),('慈愛','H2617','khesed','慈愛'),('罪孽','H5771','avon','罪孽'),('注目','H6491','pqukhot','睜開的')],
gram=['**{H6381}**（pala，難成）：「**在你沒有難成的事**」。**這個字，在二十七節神再說一次：「豈有我難成的事嗎？」****耶利米的禱告，與神的回答，用的是同一個字。**','**{H2220}**（zeroa，膀臂）：「**伸出來的膀臂**」。**這是出埃及的語言**（申四34）。**耶利米禱告時，回到了出埃及的故事。**'],
exp=['耶利米交完契，**便禱告**。**這個禱告，非常誠實。****他先講神的大：創造天地，沒有難成的事。****再講神的性格：施慈愛與千萬人，也不放過罪孽。****這就是為什麼他可以接下去講神的作為。**','十八節的**「將父親的罪孽報應在他後世子孫的懷中」**，是**出埃及記三十四章7節的語言**。請與**三十一章29--30節對讀**：**各人必因自己的罪死亡**。**兩處並不矛盾：一個說到罪的影響會延續；一個說到責任是各人的。****神的公義，兩面都有。**','十九節：**謀事有大略，行事有大能，注目觀看世人一切的舉動。****神的眼，是睜開的。****這是一個很重要的前設：耶利米知道，神看見了一切，包括這個圍城。****禱告，從「神是誰」開始。**']),
dict(a=20,z=25,star=3,lit=L(20,25),
key=[('神蹟','H226','otot','神蹟、記號'),('奇事','H4159','mofetim','奇事'),('流奶與蜜','H2100','zavat khalav udvash','流奶與蜜'),('不聽從','H8085','shamu','聽見、聽從'),('築壘','H5550','hasolot','攻城的土壘'),('看見','H7200','raah','看見')],
gram=['**{H5550}**（solelah，土壘）：「**築壘要攻取這城**」。**這是古代攻城的方法：在城牆外堆起土坡，一直堆到城牆高。****耶利米看著土壘越堆越高，卻被神叫去買地。**','**{H7200}**（ra’ah，看見）：「**你也看見了**」。**耶利米對神說：祢所說的都成就了，祢也看見了。****這是一句帶著委屈的話。**'],
exp=['二十到二十三節，**耶利米回顧歷史：出埃及的神蹟、賜地、百姓不聽從、災禍臨到。****這是一個完整的故事：神作了一切，人不聽從，所以今日圍城。****他用歷史，來為眼前的處境，作一個誠實的註解。**','二十四、二十五節，是**禱告的轉折**：**看哪，敵人已經來到，築壘要攻取這城。****你所說的話都成就了。****可是，祢卻對我說：要用銀子為自己買那塊地。****其實這城已交在迦勒底人的手中了。****這裡，是耶利米的困惑。**','請留意：**耶利米沒有隱藏他的困惑。****他沒有說「我完全明白」，而是說：主啊，祢叫我買田，但城已經要被攻陷了，這是為什麼？****這是一個誠實的禱告：順服了，卻不明白。****神喜歡這樣的禱告。**']),
dict(a=26,z=29,star=3,lit=L(26,29),
key=[('血氣','H1320','basar','肉體、凡有血氣者'),('難成','H6381','yippale','奇妙、困難'),('放火','H3341','vehitsitu','點火'),('巴力','H1168','labaal','巴力'),('燒香','H6999','qitru','燒香'),('澆奠','H5262','nesakhim','澆酒'),('別神','H312','akherim','別的神')],
gram=['**{H6381}**（pala，難成）：**這是三十二章17節耶利米禱告所用的同一個字。****耶利米說：祢沒有難成的事。****神回答：豈有我難成的事嗎？****神把他的禱告，原封不動地還給他，變成一個問句。**','**{H6999}**（qatar，燒香）：「**在這房屋上，人曾向巴力燒香**」。**古時的屋頂是平的，是人常去的地方。****這節說的是在日常的屋頂上，向巴力獻祭。**'],
exp=['二十六、二十七節，是**神給耶利米的回答，十分簡潔**：**「我是耶和華，是凡有血氣者的神，豈有我難成的事嗎？」****神沒有解釋為什麼買田，也沒有化解他的困惑，而是回到祂自己：我是誰。****有時候，最好的答案，不是解釋，而是認識那位發問的神。**','二十八、二十九節，**神緊接著，是同樣誠實的審判：我必將這城交付迦勒底人，他必攻取，放火焚燒。****神沒有說，因為你買了田，城就不會被攻陷。****買田不是避免審判，而是在審判之中，預備重建。**','請留意**二十九節的細節：向巴力燒香，向別神澆奠，惹我發怒。****審判的原因，具體、明確。****神不是無緣無故地毀壞，而是因為百姓一再離開祂。**']),
dict(a=30,z=35,star=3,lit=L(30,35),
key=[('幼年','H5271','neurim','青年、幼年'),('早起來','H7925','hashkem','早起'),('背向','H6203','oref','頸項、背'),('可憎之物','H8251','shiqutsehem','可憎之物'),('欣嫩','H2011','hinnom','欣嫩（地名）'),('邱壇','H1116','bamot','邱壇、高處'),('摩洛','H4432','lamolekh','摩洛')],
gram=['**{H6203}**（oref，頸項、背）：「**以背向我，不以面向我**」。**這是一個很具體的身體動作：把頸項轉過去。****神說，他們用背對著我。**','**{H4432}**（Molekh，摩洛）：**摩洛，是一個古代近東的神的名字，與獻兒女的可憎行為連在一起。****本講義，不描寫細節，只強調神的話：「這並不是我所吩咐的，也不是我心所起的意。」**'],
exp=['三十到三十二節，**是神的控訴：自從幼年以來，專行我眼中看為惡的事。****從建造那日直到今日。****君王、首領、祭司、先知，並猶大的眾人。****這是全面的敗壞。**','三十三節很令人心痛：**他們以背向我，不以面向我；我雖從早起來教訓他們，他們卻不聽從。****神從早起來，一再差遣、一再教導。****這句話，與二十九章19節呼應。**','三十四、三十五節，**說到最可怕的事：把可憎之物，設立在稱為我名下的殿中；在欣嫩子谷，建築巴力的邱壇，使自己的兒女經火歸摩洛。****神說：這並不是我所吩咐的，也不是我心所起的意。****這是一個重要的宣告：神沒有要求這樣的事，甚至沒有想過。**']),
dict(a=36,z=38,star=3,lit=L(36,38),
key=[('招聚','H6908','mqabtsam','聚集'),('怒氣','H639','bkhapi','怒氣'),('忿怒','H2534','uvkhamati','忿怒'),('惱恨','H7110','uvqetsef','惱怒'),('安然','H983','lavetakh','安穩、安然'),('子民','H5971','leam','子民'),('神','H430','leloqim','神')],
gram=['**{H983}**（betakh，安然）：「**使他們安然居住**」。**這個字，常用來形容沒有人使他們害怕的安穩。****與三十章10節呼應。**','**{H6908}**（qavats，招聚）：「**日後我必從那裡將他們招聚出來**」。**神把他們趕散，也是神把他們招聚。****趕散與招聚，都是同一位神的作為。**'],
exp=['**「現在」**，是一個轉彎。**前面是控訴與審判；從三十六節開始，神說：現在論到這城。****這城雖然要被攻陷，但神有後話。****審判不是最後一句話。**','三十七節說：**我在怒氣、忿怒和大惱恨中，將以色列人趕到各國。****神沒有隱藏祂的憤怒。****可是接著說：日後我必招聚他們，領他們回來，使他們安然居住。****憤怒，是真的；恢復，也是真的。**','**三十八節，是整個盟約的公式：「他們要作我的子民，我要作他們的神。」****這句話，已經在三十一章33節出現。****在這裡，被放在一個圍城的背景之下。****即使城要被毀，這個關係不會被毀。**']),
dict(a=39,z=41,star=3,lit=L(39,41),
key=[('同心同道','H259','lev ekhad vederekh ekhad','一心一道'),('敬畏','H3374','yirati','敬畏'),('永遠的約','H1285','brit olam','永遠的約'),('施恩','H3190','lehetiv','施恩、使好'),('栽','H5193','unetatim','栽種'),('歡喜','H7797','vesasti','歡喜'),('誠實','H571','beemet','誠實、真實')],
gram=['**{H259}**（ekhad，一）：「**同心同道**」，直譯是「**一個心，一條路**」。**神要賜給他們的，不只是土地，而是一個合一的心和一條共同的道路。**','**{H7797}**（sus，歡喜）：「**我必歡喜施恩與他們**」。**神不是勉強、無奈地施恩，而是歡喜地、帶著喜悅。****這是整卷書最令人驚訝的一句話。**'],
exp=['三十九節，**神應許：要使他們彼此同心同道。****這是一個很深的恢復：不只是回到土地，而是回到彼此，回到同一個方向。****北國與南國的分裂，被神親手縫合。**','四十節，**神說：要與他們立永遠的約，必隨著他們施恩，並不離開他們，且使他們有敬畏我的心。****你注意：神的約，有兩個部分：我不離開你們；我要使你們有敬畏我的心。****連「不離開神」這件事，也是神賜給的。**這與**三十一章33節**呼應。','四十一節，**說出最令人意外的一句話：我必歡喜施恩與他們，要盡心盡意、誠誠實實將他們栽於此地。****神說，我歡喜。****「盡心盡意」，原文是「用我整個的心與性命」。****神把自己整個的人，都放進這個栽種裡。**']),
dict(a=42,z=44,star=3,lit=L(42,44),
key=[('大禍','H7451','haraah','災禍、惡'),('福樂','H2896','hatovah','美好、福樂'),('荒涼','H8077','shmamah','荒涼'),('置買','H7069','vniqneh','被買'),('畫押','H3789','vekhatov','寫'),('封緘','H2856','vekhatom','蓋印'),('見證','H5707','edim','見證人')],
gram=['**{H2896}**（tov，美善、福樂）：「**福樂**」。**這個字，與「災禍」（H7451）是對舉的：我怎樣使大禍臨到，也怎樣使福樂臨到。****同一位神，兩種作為，都是真實的。**','**{H8077}**（shemamah，荒涼）：「**這地是荒涼、無人民、無牲畜**」。**這是百姓所說的話，也是眼前的現實。****神說，他們所說的，我要翻轉。**'],
exp=['四十二節，**神說：我怎樣使這一切大禍臨到這百姓，我也要照樣使我所應許他們的一切福樂都臨到他們。****這是一個很有重量的平行：神沒有說，禍沒有發生；祂說，禍是我作的，福也是我要作的。****可信的，不只是福的應許，也包括禍的應驗。**','四十三、四十四節，**回到買田的事：日後在這境內，必有人置買田地。****畫押、封緘、請見證人。****神把耶利米那一天做的事，放大成整個地方的未來。****一個人，在圍城中買的一塊田，成為整個地的盼望的記號。**','請留意**最後一句的細節：在便雅憫地、耶路撒冷四圍、猶大的城邑、山地、高原、南地的城邑。****神把整個地方，一個一個，點名說出來。****沒有一個地方，被神遺忘。****這一章，從一份契，走到整個地的復興。**']),
]
